import {extractFile,parseExtractedText} from './extraction.js';
import {validateDocument} from './matching-engine.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function extractAndReview(file,kind,progress){const text=await extractFile(file,progress),data=parseExtractedText(text,kind);return reviewExisting(data,text,file);}
export function reviewExisting(data,text,file=null){const kind=data.type;return new Promise(resolve=>{
 const dialog=document.createElement('dialog');dialog.className='ocr-dialog';const url=file?URL.createObjectURL(file):null;dialog.innerHTML=`<div class="dialog-top"><div><span class="eyebrow">VERIFY EXTRACTED DETAILS</span><h2>Review ${kind==='invoice'?'invoice':'purchase order'}</h2><p>OCR reads the document; field detection is best-effort. Correct missing or misread values before continuing.</p></div><button type="button" class="icon-button" data-cancel aria-label="Cancel extraction">×</button></div><div class="ocr-grid"><section><h3>Original document</h3>${!file?`<pre>${esc(text)}</pre>`:/\.pdf$/i.test(file.name)?`<iframe title="Original PDF" src="${url}"></iframe>`:`<img alt="Uploaded document" src="${url}">`}<details><summary>Extracted text</summary><pre>${esc(text)}</pre></details></section><form><div class="ocr-fields">${[['vendor','Vendor'],['number','Document number'],['poNumber','PO reference'],['currency','Currency'],['tax','Tax'],['total','Total']].map(([k,l])=>`<label>${l}<input name="${k}" value="${esc(data[k])}" required ${['tax','total'].includes(k)?'type="number" min="0" step="0.01"':''}></label>`).join('')}</div><h3>Line items</h3><p>Match the same SKU on both documents. Add any rows detection missed.</p><div class="ocr-lines"></div><button type="button" class="text-button" data-add>+ Add line item</button><label class="review-confirm"><input type="checkbox" required> I checked these fields and line items against the original document.</label><p class="ocr-error" role="alert"></p><button class="button primary" type="submit">Use verified document</button></form></div>`;document.body.append(dialog);
 const lineHost=dialog.querySelector('.ocr-lines');function addLine(l={}){const row=document.createElement('div');row.className='ocr-line';row.innerHTML=[['sku','SKU','text'],['description','Description','text'],['quantity','Quantity','number'],['unitPrice','Unit price','number']].map(([k,label,type])=>`<label>${label}<input data-key="${k}" type="${type}" ${type==='number'?`min="${k==='quantity'?1:0}" step="${k==='quantity'?1:'.01'}"`:''} value="${esc(l[k])}" required></label>`).join('')+'<button type="button" class="text-button danger" aria-label="Remove line">Remove</button>';row.querySelector('button').onclick=()=>row.remove();lineHost.append(row);}
 (data.lines.length?data.lines:[{}]).forEach(addLine);dialog.querySelector('[data-add]').onclick=()=>addLine();function close(value){dialog.close();dialog.remove();if(url)URL.revokeObjectURL(url);resolve(value);}dialog.querySelector('[data-cancel]').onclick=()=>close(null);dialog.oncancel=e=>{e.preventDefault();close(null);};dialog.querySelector('form').onsubmit=e=>{e.preventDefault();try{const form=new FormData(e.target);const d={...data};for(const k of ['vendor','number','poNumber','currency'])d[k]=String(form.get(k)).trim();for(const k of ['tax','total'])d[k]=Number(form.get(k));d.lines=[...lineHost.children].map(row=>Object.fromEntries([...row.querySelectorAll('input')].map(i=>[i.dataset.key,['quantity','unitPrice'].includes(i.dataset.key)?Number(i.value):i.value.trim()])));validateDocument(d,kind);d.sourceText=text;d.sourceFilename=file?.name||'inbox-source.txt';d.extractionReviewed=true;close(d);}catch(err){dialog.querySelector('.ocr-error').textContent=err.message;}};dialog.showModal();});}
